package com.yilu.yinling.user.service.impl;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import com.yilu.yinling.common.exception.BusinessException; import com.yilu.yinling.security.JwtTokenProvider; import com.yilu.yinling.user.dto.AuthDto; import com.yilu.yinling.user.entity.User; import com.yilu.yinling.user.mapper.UserMapper; import com.yilu.yinling.user.service.UserService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service @org.springframework.context.annotation.Profile("!demo") public class UserServiceImpl implements UserService { private final UserMapper mapper; private final PasswordEncoder encoder; private final JwtTokenProvider jwt; public UserServiceImpl(UserMapper m,PasswordEncoder e,JwtTokenProvider j){mapper=m;encoder=e;jwt=j;} private AuthDto.UserView view(User u){return new AuthDto.UserView(u.getId(),u.getUsername(),u.getRealName(),u.getPhone(),u.getAvatarUrl());} public AuthDto.LoginResponse login(AuthDto.LoginRequest r){User u=mapper.selectOne(new QueryWrapper<User>().eq("username",r.username())); if(u==null||!encoder.matches(r.password(),u.getPassword())||u.getStatus()!=null&&u.getStatus()==0) throw new BusinessException("用户名或密码错误"); var roles=mapper.selectRoleCodes(u.getId()); if(roles==null||roles.isEmpty()) roles=java.util.List.of("USER"); return new AuthDto.LoginResponse(jwt.create(u.getId(),u.getUsername(),roles),view(u));} public AuthDto.UserView register(AuthDto.RegisterRequest r){if(mapper.selectCount(new QueryWrapper<User>().eq("username",r.username()))>0) throw new BusinessException("用户名已存在"); User u=new User();u.setUsername(r.username());u.setPassword(encoder.encode(r.password()));u.setRealName(r.realName());u.setPhone(r.phone());u.setStatus(1);mapper.insert(u);return view(u);} public AuthDto.UserView current(Long id){return view(mapper.selectById(id));} public AuthDto.UserView update(Long id,AuthDto.UserView r){User u=mapper.selectById(id);if(u==null)throw new BusinessException("用户不存在");u.setRealName(r.realName());u.setPhone(r.phone());u.setAvatarUrl(r.avatarUrl());mapper.updateById(u);return view(u);} }
